using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(IDbContextFactory<ApplicationDbContext> contextFactory) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        return await context.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
    }

    public async Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        var query = context.Shipments.AsQueryable();
        if (status.HasValue)
            query = query.Where(s => s.Status == status.Value);
        return await query.OrderByDescending(s => s.ShippedDate).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        return await context.Shipments.FirstOrDefaultAsync(
            s => s.TrackingNumber == trackingNumber);
    }

    public async Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        var shipment = await context.Shipments.FindAsync(id);
        if (shipment is null) return null;

        shipment.Status = newStatus;
        if (newStatus == ShipmentStatus.Delivered)
            shipment.ActualDelivery = DateTime.UtcNow;

        await context.SaveChangesAsync();
        return shipment;
    }
}

