using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
            e.Property(s => s.TrackingNumber).HasMaxLength(20);
            e.Property(s => s.Origin).HasMaxLength(200);
            e.Property(s => s.Destination).HasMaxLength(200);
            e.Property(s => s.RecipientName).HasMaxLength(200);
            e.Property(s => s.CarrierName).HasMaxLength(100);
        });

        SeedShipments(builder);
    }

    private static void SeedShipments(ModelBuilder builder)
    {
        var baseDate = new DateTime(2026, 5, 20, 0, 0, 0, DateTimeKind.Utc);

        builder.Entity<Shipment>().HasData(
            new Shipment
            {
                Id = 1, TrackingNumber = "TRK-100001",
                Origin = "New York, USA", Destination = "London, UK",
                Status = ShipmentStatus.InTransit,
                ShippedDate = baseDate,
                EstimatedDelivery = baseDate.AddDays(7),
                RecipientName = "Alice Johnson", CarrierName = "OceanFreight Co.", WeightKg = 25.5
            },
            new Shipment
            {
                Id = 2, TrackingNumber = "TRK-100002",
                Origin = "Shanghai, China", Destination = "Los Angeles, USA",
                Status = ShipmentStatus.Delivered,
                ShippedDate = baseDate.AddDays(-10),
                EstimatedDelivery = baseDate.AddDays(-3),
                ActualDelivery = baseDate.AddDays(-2),
