var shipmentApi = app.MapGroup("api/shipments");

shipmentApi.MapGet("/", async (ShipmentStatus? status, IDbContextFactory<ApplicationDbContext> dbFactory) =>
{
    await using var db = await dbFactory.CreateDbContextAsync();
    var query = db.Shipments.AsQueryable();
    if (status.HasValue)
        query = query.Where(s => s.Status == status.Value);
    return Results.Ok(await query.OrderByDescending(s => s.ShippedDate).ToListAsync());
});

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, IDbContextFactory<ApplicationDbContext> dbFactory) =>
{
    await using var db = await dbFactory.CreateDbContextAsync();
    var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipmentApi.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, IDbContextFactory<ApplicationDbContext> dbFactory) =>
{
    await using var db = await dbFactory.CreateDbContextAsync();
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Status = newStatus;
    if (newStatus == ShipmentStatus.Delivered)
        shipment.ActualDelivery = DateTime.UtcNow;

    await db.SaveChangesAsync();
    return Results.Ok(shipment);
});

app.MapStaticAssets();
app.MapRazorComponents<App>()
    .AddInteractiveServerRenderMode()
    .AddInteractiveWebAssemblyRenderMode()
    .AddAdditionalAssemblies(typeof(ShipmentTracker.Client._Imports).Assembly);

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

